"""Pinned transactional installer for isolated phone tasks."""
import base64,fcntl,hashlib,json,os,socket,subprocess,tempfile,time
from pathlib import Path
MANIFEST = {'automation/server/phone_ui.py': {'data': '', 'sha256': '85c2583cdd23480008b1729512daa7af6b6692b1b307adbcefe417a97d33931f', 'previous': ['e0e4a114d71582f516b1ca40f00a2d95ef321bb85d7aa3742f449bbca7ce8b96'], 'systemd': False}, 'automation/server/phone_tasks.py': {'data': '', 'sha256': '8b00bdaaa32635e39e8e0249f2d46da8aa19965364b6f396ac9cf14a97dfd34b', 'previous': ['ef8fdeb1e607f088745c4045bbddf5f7c5ed7af9357b2e732e12652c08c66046'], 'systemd': False}, 'automation/server/phone_view.py': {'data': '', 'sha256': 'db05dbbfe43d2be15d8ab3375d07cd2e0a4d6176dc171bc59e53a901b423c38f', 'previous': ['1dd1c80ebbe5c65c3d26e7d8fbdee1fc26db6597b88ef690e43505a06cfa753b'], 'systemd': False}, 'automation/server/test_phone_view.py': {'data': '', 'sha256': '4e702a42278861b5d4a6273f33ab2087a2902dc27458c073d427fbc20d8c3626', 'previous': [], 'systemd': False}, 'automation/server/steam_consent.py': {'data': '', 'sha256': 'd411f236871b3db0bf3661e2f6e0c5b743c1284fd4b82c0a41750d0fc7b8499f', 'previous': [], 'systemd': False}, 'automation/server/test_steam_consent.py': {'data': '', 'sha256': '3759742bd28ffe8e70a29708fb835fb23f24c131b61ecf35966c9d4d551236fa', 'previous': [], 'systemd': False}, 'automation/server/test_phone_panel_browser.py': {'data': '', 'sha256': '0ecf26a0c94140a4c2604199334bb18b1490ff36a2e621829acfd3f28f56cd0d', 'previous': [], 'systemd': False}}

def digest(raw):
    return hashlib.sha256(raw).hexdigest()

def prepare(root,systemd,manifest=MANIFEST):
    plans=[]
    for name,item in manifest.items():
        raw=base64.b64decode(item['data'],validate=True)
        if digest(raw)!=item['sha256']:raise RuntimeError('Installer content mismatch: '+name)
        if name.endswith('.py'):compile(raw,name,'exec')
        target=(systemd/Path(name).name) if item['systemd'] else (root/name)
        if target.is_symlink():raise RuntimeError('Unexpected symlink: '+name)
        before=target.read_bytes() if target.exists() else None
        if before is not None and digest(before) not in item['previous']+[item['sha256']]:
            raise RuntimeError('Unknown installed version; no files changed: '+name)
        plans.append((target,raw,before,target.stat() if target.exists() else None))
    return plans

def replace(target,raw,uid,gid,mode):
    target.parent.mkdir(parents=True,exist_ok=True)
    fd,temp=tempfile.mkstemp(prefix='.fh6-update-',dir=target.parent)
    try:
        with os.fdopen(fd,'wb') as stream:
            stream.write(raw);stream.flush();os.fsync(stream.fileno())
            os.fchown(stream.fileno(),uid,gid);os.fchmod(stream.fileno(),mode)
        os.replace(temp,target)
    finally:
        if Path(temp).exists():Path(temp).unlink()

def main():
    if os.geteuid()!=0 or socket.gethostname()!='fh6-collector':
        raise RuntimeError('Run only as root inside CT109 fh6-collector')
    root=Path('/opt/fh6/repo');store=Path('/var/lib/fh6');systemd=Path('/etc/systemd/system')
    with (store/'runner.lock').open('a+b') as runner_lock,(root/'automation/runs/refresh/process.lock').open('a+b') as guard_lock:
        for lock in [runner_lock,guard_lock]:fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        for unit in ['fh6-refresh.service','fh6-manual.service','fh6-recovery-run.service','fh6-phone-tasks.service']:
            if not (systemd/unit).exists():continue
            status=subprocess.run(['systemctl','show',unit,'--property=ActiveState','--value'],capture_output=True,text=True,timeout=10)
            if status.returncode or status.stdout.strip() in {'active','activating','deactivating','reloading'}:
                raise RuntimeError('A pipeline or task is running; no files changed')
        plans=prepare(root,systemd)
        backup=store/'repairs'/('panel-design-'+str(time.time_ns()));backup.mkdir(parents=True,mode=0o700)
        metadata=[]
        for index,(target,raw,before,stat) in enumerate(plans):
            if before is not None:
                saved=backup/str(index);saved.write_bytes(before);saved.chmod(0o600)
            metadata.append(dict(path=str(target),existed=before is not None,uid=stat.st_uid if stat else 0,gid=stat.st_gid if stat else 0,mode=stat.st_mode&0o7777 if stat else 0o644))
        (backup/'metadata.json').write_text(json.dumps(metadata,indent=2))
        applied=[]
        timer_was_active=subprocess.run(['systemctl','is-active','--quiet','fh6-phone-tasks.timer']).returncode==0
        timer_was_enabled=subprocess.run(['systemctl','is-enabled','--quiet','fh6-phone-tasks.timer']).returncode==0
        try:
            for target,raw,before,stat in plans:
                replace(target,raw,stat.st_uid if stat else 0,stat.st_gid if stat else 0,stat.st_mode&0o7777 if stat else 0o644)
                applied.append((target,before,stat))
            subprocess.run(['systemd-analyze','verify',str(systemd/'fh6-phone-tasks.service'),str(systemd/'fh6-phone-tasks.timer')],check=True,timeout=30)
            subprocess.run(['python3',str(root/'automation/server/test_phone_tasks.py')],cwd=root,check=True,timeout=60)
            subprocess.run(['python3',str(root/'automation/server/test_phone_view.py')],cwd=root,check=True,timeout=60)
            subprocess.run(['python3',str(root/'automation/server/test_steam_consent.py')],cwd=root,check=True,timeout=60)
            subprocess.run(['python3',str(root/'automation/server/test_server.py')],cwd=root,check=True,timeout=300)
            subprocess.run(['/opt/fh6/venv/bin/python',str(root/'automation/server/test_phone_panel_browser.py')],cwd=root,check=True,timeout=180)
            subprocess.run(['systemctl','daemon-reload'],check=True,timeout=30)
            subprocess.run(['systemctl','restart','fh6-phone.service'],check=True,timeout=30)
            subprocess.run(['systemctl','enable','--now','fh6-phone-tasks.timer'],check=True,timeout=30)
            subprocess.run(['systemctl','is-active','--quiet','fh6-phone.service','fh6-phone-tasks.timer'],check=True,timeout=30)
        except BaseException:
            subprocess.run(['systemctl','stop','fh6-phone-tasks.timer','fh6-phone-tasks.service'],timeout=30)
            if not timer_was_enabled:subprocess.run(['systemctl','disable','fh6-phone-tasks.timer'],timeout=30)
            for target,before,stat in reversed(applied):
                if before is None:target.unlink(missing_ok=True)
                else:replace(target,before,stat.st_uid,stat.st_gid,stat.st_mode&0o7777)
            subprocess.run(['systemctl','daemon-reload'],timeout=30)
            subprocess.run(['systemctl','restart','fh6-phone.service'],timeout=30)
            if timer_was_active:subprocess.run(['systemctl','start','fh6-phone-tasks.timer'],timeout=30)
            raise
        print('FH6_PANEL_UPDATED timer=active; isolated tests passed; no real task submitted')
        print('BACKUP='+str(backup))

if __name__=='__main__':main()
